    <label>Priority <select id="pr">${['urgent', 'high', 'medium', 'low', 'none'].map((x) => `<option ${x === i.priority ? 'selected' : ''}>${x}</option>`).join('')}</select></label>
    <button id="watch">Watch</button><button id="del">Delete</button></div>
